From 8ebce522150117ae78bb75aeeb00118babf6f5aa Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:26:38 +0100
Subject: [PATCH] applets/taskmanager: add "Close All Except Last Used" to
 grouped tasks

With several windows of the same app grouped together, the only way to
reduce clutter was closing them one by one. Grouped tasks now also offer
an action that closes all of their windows but the most recently used.

BUG: 524331
---
 applets/taskmanager/qml/ContextMenu.qml | 28 +++++++++++++++++++++++++
 1 file changed, 28 insertions(+)

diff --git a/applets/taskmanager/qml/ContextMenu.qml b/applets/taskmanager/qml/ContextMenu.qml
index fe837049fc..1291a718aa 100644
--- a/applets/taskmanager/qml/ContextMenu.qml
+++ b/applets/taskmanager/qml/ContextMenu.qml
@@ -869,4 +869,32 @@ PlasmaExtras.Menu {
             tasksModel.requestClose(menu.modelIndex);
         }
     }
+
+    PlasmaExtras.MenuItem {
+        visible: closeWindowItem.visible && menu.get(TaskManager.AbstractTasksModel.IsGroupParent)
+
+        enabled: closeWindowItem.enabled
+
+        text: i18nc("@action:inmenu close all windows of the group except the most recently used one", "Close All &Except Last Used")
+        icon: "window-close"
+
+        onClicked: {
+            let lastUsedRow = -1;
+            let lastUsedTime = -Infinity;
+            TaskManagerApplet.TaskTools.foreachChildTask((childIndex) => {
+                const lastActivated = tasksModel.data(childIndex, TaskManager.AbstractTasksModel.LastActivated);
+                const time = lastActivated ? lastActivated.getTime() : -Infinity;
+                if (lastUsedRow === -1 || time > lastUsedTime) {
+                    lastUsedRow = childIndex.row;
+                    lastUsedTime = time;
+                }
+            }, menu.modelIndex, tasksModel);
+
+            TaskManagerApplet.TaskTools.foreachChildTask((childIndex) => {
+                if (childIndex.row !== lastUsedRow) {
+                    tasksModel.requestClose(childIndex);
+                }
+            }, menu.modelIndex, tasksModel);
+        }
+    }
 }
